    "clozeLines": [
      "1. 图灵全名可写作（[[艾兰·图灵]]）（Alan Turing），也可写作艾伦·麦席森·图灵（Alan Mathison Turing）。",
      "2. 1936年，图灵发表《（[[论可计算数及其在判定问题中的应用]]）》。",
      "3. 图灵机英文为（[[Turing Machine]]），缩写为（[[TM]]）。",
      "4. 图灵机主要由两部分组成：一条（[[无限长的纸带]]）和一个（[[读写头]]）。",
      "5. 图灵机是一个（[[数学模型]]）、思维机器，不是一台（[[实际的计算机]]）。",
      "6. 图灵机所有可能状态数目是（[[有限]]）的，其中有一个特殊状态称为（[[停机状态]]）。",
      "7. 一个问题需要（[[一台图灵机]]），不同的问题需要（[[不同的图灵机]]）。",
      "8. 图灵机证明了（[[通用计算理论]]），奠定了（[[可计算性理论]]）的基础。",
      "9. 通用图灵机英文为（[[Universal Turing Machine]]），缩写为（[[UTM]]）。",
      "10. 通用图灵机能够解决（[[所有图灵机能解决的所有问题]]）。",
      "11. 现代计算机的功能不可能（[[超越图灵机]]），现代计算机能够实现的功能是图灵机功能的（[[子集]]）。",
      "12. 只有图灵机能解决的计算问题，（[[实际计算机]]）才能解决；图灵机不可计算的问题，现代计算机也（[[不能计算]]）。",
      "13. 教材中使用“图灵机”这一概念时，通常指的是（[[通用图灵机]]）。",
      "14. 丘奇-图灵论题认为，一切直觉上可计算的函数都可用（[[图灵机]]）计算，反之亦然。",
      "15. 一个问题是可计算的，当且仅当它能被图灵机在（[[有限步骤]]）内解决。",
      "16. 存在图灵机不能解决的问题，例如（[[停机问题]]）。",
      "17. 图灵测试来源于1950年的《（[[Computing Machinery and Intelligence]]）》。",
      "18. 图灵测试用于测试计算机是否具有人类智能，方法是通过（[[人机对话]]）。",
      "19. PDF指出，目前还没有任何一台计算机被公认为（[[通过图灵测试]]）。",
      "20. 图灵被称为（[[计算机科学的奠基人]]）。",
      "21. 图灵奖由（[[美国计算机学会]]）（ACM）为纪念图灵而创立，是计算机领域（[[最高奖项]]）。",
      "22. PDF列出的图灵奖华人获奖者是（[[姚期智]]）。"
    ],
