    "pdf": "./imports/day-01/alan-turing-source.pdf",
    "pdfTextLines": [
      "参阅：教材 P001~003；真题：2016-11 单选、2017-22 判断。",
      "考点：图灵机、通用图灵机、图灵测试、图灵奖。",
      "全名：艾兰·图灵（Alan Turing）或艾伦·麦席森·图灵（Alan Mathison Turing）。",
      "1936年论文：《论可计算数及其在判定问题中的应用》。",
      "图灵机（Turing Machine，TM）主要由无限长的纸带和读写头组成，是数学模型、思维机器，不是实际计算机。",
      "图灵机状态数有限，具有停机状态；一个问题需要一台图灵机，不同问题需要不同图灵机。",
      "图灵机奠定可计算性理论基础，并为计算机实现可能性和主要架构提供理论支撑。",
      "通用图灵机（Universal Turing Machine，UTM）能够解决所有图灵机能解决的问题。",
      "现代计算机功能不能超越图灵机，其可实现功能是图灵机功能的子集。",
      "丘奇-图灵论题：可计算问题能由图灵机在有限步骤内解决；停机问题是不可计算问题。",
      "图灵测试出自1950年《Computing Machinery and Intelligence》，通过人机对话测试机器是否具有人类智能。",
      "图灵被称为计算机科学的奠基人。",
      "图灵奖由美国计算机学会（ACM）设立，是计算机领域最高奖项；PDF列出的华人获奖者为姚期智。"
    ],
