    "id": "D02-ENG-NOTE-005",
    "order": 18,
    "title": "句子成分及句子类型（扫描笔记）",
    "category": "英语扫描讲义",
    "range": "句子成分与五种基本句型 · 第2天 · 7.16",
    "oneLine": "完整归档主语、谓语、宾语、表语、宾补、定语、状语、同位语及五种基本句型的扫描讲义。",
    "keywords": [
      "句子成分",
      "主语",
      "谓语",
      "宾语",
      "表语",
      "宾语补足语",
      "定语",
      "状语",
      "同位语",
      "五种基本句型",
      "SV",
      "SVO",
      "SVP",
      "SVOO",
      "SVOC"
    ],
    "memoBlocks": [
      {
        "title": "五种基本句型复习",
        "understanding": [
          "主语+谓语（SV）：谓语通常是不及物动词，如His friend left。",
          "主语+谓语+宾语（SVO）：谓语通常是及物动词，如He missed his friends。",
          "主语+谓语+间接宾语+直接宾语（SVOO）：如He sent his friend a gift。",
          "主语+谓语+宾语+宾语补足语（SVOC）：如It made his friend happy。",
          "主语+系动词+表语（SVP）：如They are best friends。"
        ],
        "mustKnow": []
      },
      {
        "title": "句子成分总览",
        "understanding": [
          "英语常见句子成分包括主语、谓语、宾语、表语、宾语补足语、定语、状语和同位语。",
          "主语是动作的发出者或句子说明的对象；谓语说明主语的动作或状态。",
          "宾语是谓语动作的承受者；表语说明主语的身份、特征或状态；宾补补充说明宾语。",
          "定语修饰名词或代词；状语说明时间、地点、方式、原因、结果等；同位语解释说明前面的名词。"
        ],
        "mustKnow": []
      },
      {
        "title": "主语与谓语的常见形式",
        "understanding": [
          "名词、代词、数词、the+形容词、不定式、动名词和从句都可以作主语。",
          "形式主语it可替代较长的不定式或从句，如It is important to study English every day。",
          "英语句子必须有谓语动词；一个独立分句通常只有一套谓语结构。",
          "实义动词、助动词+实义动词、情态动词+实义动词、系动词+表语都可构成谓语；非谓语动词本身不能独立充当谓语。"
        ],
        "mustKnow": []
      },
      {
        "title": "宾语、表语、宾补、定语、状语与同位语",
        "understanding": [
          "宾语可由名词、代词、不定式、动名词、复合宾语结构或宾语从句等充当。",
          "表语位于系动词之后，可由名词、代词、形容词、介词短语、动名词、不定式或表语从句充当。",
          "宾语补足语说明宾语的身份或状态，如We elected him president、The news made her happy。",
          "定语既可前置，也可后置；状语常按“方式+地点+时间”排列，地点和时间通常由小到大。",
          "同位语紧跟名词，对其进行解释说明；同位语从句常用that引导。"
        ],
        "mustKnow": []
      }
    ],
    "examples": [
      {
        "en": "To study English every day is important.",
        "cn": "不定式短语作主语。",
        "note": "也可改为It is important to study English every day。"
      },
      {
        "en": "I find it difficult to get up early.",
        "cn": "it作形式宾语，difficult作宾补。",
        "note": ""
      },
      {
        "en": "The man who stands on the stage is a famous actor.",
        "cn": "who引导定语从句，修饰the man。",
        "note": ""
      },
      {
        "en": "Feeling tired, I went home.",
        "cn": "现在分词短语作状语。",
        "note": ""
      }
    ],
