    "id": "D03-MATH-NOTE-001",
    "order": 63,
    "title": "求解步骤——反函数",
    "oneLine": "求反函数三步：从y=f(x)反解x；交换x、y；确定反函数定义域为原函数值域。",
    "keywords": [
      "反函数",
      "反解",
      "交换变量",
      "原函数值域"
    ],
    "memoBlocks": [
      {
        "title": "反函数的求解步骤",
        "mustKnow": [
          "第一步：从y=f(x)中反解出x=f⁻¹(y)。",
          "第二步：交换变量x、y，得到y=f⁻¹(x)。",
          "第三步：求反函数定义域，它等于原函数的值域。"
        ],
        "understanding": [
          "反函数把原函数的“输入—输出”关系反过来，所以交换变量后，原函数值域成为反函数定义域。",
          "原函数必须在所讨论区间上具有一一对应关系，才能存在反函数。"
        ]
      }
    ],
