      "core": [
        "从y=f(x)反解x。",
        "交换x与y。",
        "反函数定义域=原函数值域。"
      ],
      "method": [
        "先确认原函数在给定区间是否一一对应。",
        "反解后不要忘记交换变量。",
        "最后单独检查定义域。"
      ],
      "mistakes": [
        "最常见漏项是只求表达式，不写反函数定义域。"
      ],
      "conclusion": "反解x，交换x/y，定义域取原值域。",
      "mnemonic": "反解 → 交换 → 原值域",
      "sourceLabel": "第3天 · 7.17 · 数学笔记"
