      "core": [
        "sin x、cos x的值域是[-1,1]。",
        "arcsin、arccos、arctan、arccot的值域均为有限区间。"
      ],
      "method": [
        "判断有界时只看函数值能否超过某个固定上下界。"
      ],
      "mistakes": [
        "定义域无界不代表函数无界。"
      ],
      "conclusion": "正弦余弦与常见反三角函数都属于有界函数。",
