    "title": "some与any",
    "oneLine": "some常用于肯定句和表示请求邀请的疑问句；any常用于否定/疑问句，也可表示任何。",
    "keywords": [
      "some",
      "any",
      "请求",
      "邀请",
      "任何"
    ],
    "mustPatterns": [
      "肯定陈述句多用some。",
      "表示请求、邀请或客气语气的疑问句用some。",
      "普通疑问句和否定句多用any。",
      "any在肯定句中可表示任何。"
    ],
    "basicExplain": [
      "句型不是唯一标准，还要看说话人的语气和词义。"
    ],
    "examRefine": [
      "疑问句中若期待肯定回答、表示请求邀请，选some。"
    ],
    "confusions": [
      [
        "some",
        "any",
        "some偏肯定/请求；any偏疑问否定或“任何”。"
      ]
    ],
    "clozeLines": [
      "1. 肯定陈述句多用（[[some]]）。",
      "2. 表示请求、邀请、客气的疑问句用（[[some]]）。",
      "3. 普通疑问句和否定句多用（[[any]]）。",
      "4. any在肯定句中可表示（[[任何]]）。"
    ],
    "selfTests": [
      {
        "q": "Would you like some tea?为什么不用any？",
        "a": "该疑问句表示邀请并期待肯定回答。"
      }
    ],
